changeSet.sql:
UPDATE hiv_regimen_resolver
SET regimen = 'ABC+3TC+DTG'
WHERE regimen = 'ABC-3TC-DTG';

UPDATE ndr_code_set
SET code_description = 'ABC+3TC+DTG'
WHERE code_description = 'ABC-3TC-DTG';

UPDATE ndr_code_set
SET ndr_code = 'NDR5d0130'
WHERE code = '5d' AND code_description = 'TDF+3TC+LPV/r';

 DELETE FROM ndr_code_set
WHERE code_description = 'TDF+3TC+LPV/r' AND code != '5d';

UPDATE hiv_regimen
SET regimen_type_id = 4
WHERE description = 'TDF(300mg)+3TC(300mg)+LPV/r(200/50mg)';
